// 1. Extract the dates from the current item
const dateFrom = new Date($json.dateFrom);
const dateTo = new Date($json.dateTo);

// 2. Calculate the difference in milliseconds, then convert to days
const diffInMilliseconds = dateTo - dateFrom;
const diffInDays = diffInMilliseconds / (1000 * 60 * 60 * 24);

// 3. Determine if it's a multi-date request (>1 day is multi-date)
$json.isMultiDate = diffInDays > 1;

// 4. Return the updated item
return $json;

// ==========================================
// COMBINED NODE: Request Analysis + ActivTrak Activity
// ==========================================
// Since 'Code in JavaScript7' was the request analysis output,
// we compute those values internally first, then feed them
// into the ActivTrak evaluation.
//
// Suggestion time priority:
//   1. Filtered first/last ActivTrak activity (most accurate)
//   2. Schedule times (fallback)
//   3. +/-9 hours from the orphan punch (ultimate fallback)
// ==========================================

// ==========================================
// PART 0: RAW DATA SOURCES
// ==========================================

// --- ActivTrak Activity Sources ---
const nodeHttpReq12 = $('HTTP Request16').item.json;
const nodeMasterlist = $('Get masterlist3').item.json;
const nodeCurrent = $json;

// --- Request Analysis Sources ---
let actualAttendanceLogsRaw = [];
let removedNonBiometricLogs = [];
try {
    const rawData = $('HTTP Request15').item?.json?.data || [];
    actualAttendanceLogsRaw = rawData.filter(log => {
        const notes = log.notes;
        if (notes && typeof notes === 'string' && (notes.includes('CertificateOfAttendance') || notes.includes('CertifaicateOfAttendance'))) {
            removedNonBiometricLogs.push(log);
            return false;
        }
        return true;
    });
} catch (e) { }

let requestData = {};
let requestedLogs = [];
let doerName = "Unknown Doer";

try {
    requestData = $('If54').item?.json || {};
    const rawLogs = requestData.logs || [];

    requestedLogs = rawLogs.map(log => {
        if (!log.dateTime) {
            let dt = null;
            if (log.logDate && log.logTime) {
                const dPart = String(log.logDate).split('T')[0];
                const tPart = String(log.logTime).includes('T') ? String(log.logTime).split('T')[1] : String(log.logTime);
                dt = `${dPart}T${tPart}`;
            } else if (log.logTime) {
                dt = log.logTime;
            }
            return { ...log, dateTime: dt };
        }
        return log;
    });

    if (nodeMasterlist) {
        doerName = nodeMasterlist['Doer Name'] || doerName;
    }
} catch (e) { }


// ==========================================
// SHARED CONSTANTS & HELPERS
// ==========================================
const ONE_HOUR = 60 * 60 * 1000;
const THIRTY_MINUTES = 30 * 60 * 1000;
const FIFTEEN_MINUTES = 15 * 60 * 1000;
const TWO_MINUTES = 2 * 60 * 1000;
const NINE_HOURS_MS = 9 * 60 * 60 * 1000;

function toLocalString(timestamp) {
    const dt = new Date(timestamp + (8 * 60 * 60 * 1000));
    return dt.toISOString().replace('Z', '+08:00');
}

function getLogTime(log) {
    if (!log || typeof log.dateTime !== 'string') return NaN;
    const logDateStr = log.dateTime.includes('+') || log.dateTime.includes('Z')
        ? log.dateTime
        : `${log.dateTime}+08:00`;
    return new Date(logDateStr).getTime();
}

function getSafeTimeMs(timeStr) {
    if (!timeStr) return 0;
    const dtStr = timeStr.includes('+') || timeStr.includes('Z')
        ? timeStr
        : `${timeStr}+08:00`;
    return new Date(dtStr).getTime();
}

function getLocalMasqueradeDate(isoStringWithTimezone) {
    if (!isoStringWithTimezone) return null;
    const absoluteMs = getSafeTimeMs(isoStringWithTimezone);
    const isoPST = new Date(absoluteMs + 8 * 3600 * 1000).toISOString().split('.')[0];
    return new Date(isoPST);
}

function getActivityEndTime(activityObj) {
    if (!activityObj) return 0;
    const startMs = getSafeTimeMs(activityObj.time);
    let dur = activityObj.duration;
    if (typeof dur === 'string') dur = dur.replace(/,/g, '');
    const durSec = Number(dur) || 0;
    return startMs + (durSec * 1000);
}

const formatDateTimeT = (date) => {
    if (!date || isNaN(date.getTime())) return null;
    const pad = (n) => n.toString().padStart(2, '0');
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
};

const formatDateTimeMsg = (date) => {
    if (!date || isNaN(date.getTime())) return null;
    const pad = (n) => n.toString().padStart(2, '0');
    let hours = date.getHours();
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12;
    hours = hours ? hours : 12;
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(hours)}:${pad(date.getMinutes())}:${pad(date.getSeconds())} ${ampm}`;
};

const formatSuggestionDate = (date) => {
    if (!date || isNaN(date.getTime())) return "";
    const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
    const month = months[date.getMonth()];
    const day = date.getDate();
    let hours = date.getHours();
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12;
    hours = hours ? hours : 12;
    const mins = date.getMinutes().toString().padStart(2, '0');
    return `${month} ${day} at ${hours}:${mins} ${ampm}`;
};


// ==========================================
// PART 1: SCHEDULE PARSING (computed internally,
// previously was the output of 'Code in JavaScript7')
// ==========================================
let scheduleStr = null;
try {
    if (nodeMasterlist) {
        scheduleStr = nodeMasterlist['Sprout Schedule2'] || nodeMasterlist['Sprout Schedule'];
    }
    if (!scheduleStr) {
        const mNode = $('Get masterlist');
        let mJson = mNode?.item?.json || (typeof mNode.first === 'function' ? mNode.first()?.json : null);
        if (mJson) {
            scheduleStr = mJson['Sprout Schedule2'] || mJson['Sprout Schedule'];
        }
    }
} catch (e) { }

let scheduleTimeIn = null;
let scheduleTimeOut = null;

if (scheduleStr) {
    let cleanSchedule = String(scheduleStr).replace(/[\u200B-\u200D\uFEFF]/g, '').trim();
    const separatorRegex = /[-\u2013\u2014]|(\s+to\s+)/i;

    if (separatorRegex.test(cleanSchedule)) {
        let baseDate = new Date();
        let dateStr = requestData.dateFrom || (requestedLogs && requestedLogs.length > 0 ? (requestedLogs[0].logDate || requestedLogs[0].dateTime) : null);

        if (dateStr) {
            const dateMatch = String(dateStr).match(/(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})/);
            if (dateMatch) {
                baseDate = new Date(parseInt(dateMatch[1], 10), parseInt(dateMatch[2], 10) - 1, parseInt(dateMatch[3], 10));
            }
        }
        baseDate.setHours(0, 0, 0, 0);

        const parseTimeStr = (timeStr) => {
            if (!timeStr) return null;
            const match = timeStr.trim().match(/(\d{1,2})[.:]?(\d{2})?\s*(AM|PM)?/i);
            if (!match) return null;

            let hrs = parseInt(match[1], 10);
            const mins = match[2] ? parseInt(match[2], 10) : 0;
            const ampm = match[3] ? match[3].toUpperCase() : null;

            if (ampm === 'PM' && hrs < 12) hrs += 12;
            if (ampm === 'AM' && hrs === 12) hrs = 0;

            let d = new Date(baseDate.getTime());
            d.setHours(hrs, mins, 0, 0);
            return d;
        };

        const parts = cleanSchedule.split(separatorRegex).filter(Boolean);
        if (parts.length >= 2) {
            scheduleTimeIn = parseTimeStr(parts[0]);
            scheduleTimeOut = parseTimeStr(parts[parts.length - 1]);

            // Auto-correct Night Shift rollover
            if (scheduleTimeIn && scheduleTimeOut && scheduleTimeOut < scheduleTimeIn) {
                const hasNoInLog = !requestedLogs.some(log => log.type?.toLowerCase() === 'in');
                const hasOutLog = requestedLogs.some(log => log.type?.toLowerCase() === 'out');

                if (hasNoInLog && hasOutLog) {
                    scheduleTimeIn = new Date(scheduleTimeIn.getTime() - (24 * 60 * 60 * 1000));
                } else {
                    scheduleTimeOut = new Date(scheduleTimeOut.getTime() + (24 * 60 * 60 * 1000));
                }
            }
        }
    }
}

// ==========================================
// PART 2: BUILD THE 'sources' OBJECT
// ==========================================
// Previously, inString/outString/itemName/standardLogs came from
// $('Code in JavaScript7') which was the request analysis output.
// Now we compute them directly from the schedule + request data.
const computedInStr = scheduleTimeIn ? formatDateTimeT(scheduleTimeIn) : null;
const computedOutStr = scheduleTimeOut ? formatDateTimeT(scheduleTimeOut) : null;

const sources = {
    // These replicate what 'Code in JavaScript7' (request analysis) used to output
    inString: computedInStr ? computedInStr + '+08:00' : null,
    outString: computedOutStr ? computedOutStr + '+08:00' : null,
    itemName: doerName,
    standardLogs: requestedLogs,
    // These come from the ActivTrak HTTP requests
    activityPart1: nodeHttpReq12.activity || [],
    activityPart2: nodeCurrent.activity || [],
    // Schedule data for the ActivTrak evaluation's internal schedule parsing
    rawScheduleText: nodeMasterlist['Sprout Schedule'],
    rawSchedule2: nodeMasterlist['Sprout Schedule2']
};


// ==========================================
// PART 3: ACTIVTRAK CORE EVALUATION FUNCTION
// ==========================================
function runEvaluation(scheduleName = "Original Input", fallbackScheduleLogs = null) {

    // 1. Establish the Activity Window
    // Guard: if schedule times are null, we cannot define a window
    if (!sources.inString || !sources.outString) {
        return {
            name: sources.itemName,
            json_activity_count: sources.activityPart2.length,
            filter_range: { evaluated_schedule: scheduleName },
            raw_first_activity_time: null,
            raw_last_activity_time: null,
            first_filtered_activity: null,
            last_filtered_activity: null,
            last_filtered_activity_titleBar: null,
            isMatch: false,
            missingLog: "Both",
            closestMissedTimestamp: null,
            isLate: false,
            lateMinutes: 0,
            isUnderTime: false,
            underTimeMinutes: 0,
            matchedLogs: [],
            originalLogs: sources.standardLogs,
            matchedSource: "None",
            errorReason: "No Schedule Data Available"
        };
    }

    let windowStartMs = new Date(sources.inString).getTime();
    let windowEndMs = new Date(sources.outString).getTime();

    const reqInLog = sources.standardLogs.find(l => l.type === 'In');
    const reqOutLog = sources.standardLogs.find(l => l.type === 'Out');

    if (reqInLog) {
        const t = getLogTime(reqInLog);
        if (!Number.isNaN(t)) windowStartMs = t;
    }
    if (reqOutLog) {
        const t = getLogTime(reqOutLog);
        if (!Number.isNaN(t)) windowEndMs = t;
    }

    // Handle Night Shifts crossing midnight
    if (windowEndMs < windowStartMs) {
        windowEndMs += (24 * 60 * 60 * 1000);
    }
    const extendedEndTimeMs = windowEndMs + (5 * 60 * 1000);

    const filterRange = {
        evaluated_schedule: scheduleName,
        start: toLocalString(windowStartMs),
        strict_end: toLocalString(windowEndMs),
        extended_end: toLocalString(extendedEndTimeMs)
    };

    // 2. Filter the Activities
    const allActivities = [...sources.activityPart1, ...sources.activityPart2];
    let rawFirstTime = null;
    let rawLastTime = null;
    let first_activity_str = null;
    let last_activity_str = null;
    let last_activity_title_bar = null;

    if (allActivities.length > 0) {
        const sortedRawActivities = [...allActivities].sort((a, b) => getSafeTimeMs(a.time) - getSafeTimeMs(b.time));
        rawFirstTime = sortedRawActivities[0].time;
        rawLastTime = toLocalString(getActivityEndTime(sortedRawActivities[sortedRawActivities.length - 1]));

        const filteredActivities = allActivities.filter(activity => {
            const activityTime = getSafeTimeMs(activity.time);
            return activityTime >= windowStartMs && activityTime <= extendedEndTimeMs;
        });

        if (filteredActivities.length > 0) {
            filteredActivities.sort((a, b) => getSafeTimeMs(a.time) - getSafeTimeMs(b.time));

            // Exclude "Passive" activities and offline IPs — they don't represent real work
            const activeFiltered = filteredActivities.filter(a => a.titleBar !== "Passive" && a.publicIp !== "offline");

            if (activeFiltered.length > 0) {
                first_activity_str = activeFiltered[0].time;

                const lastFilteredObject = activeFiltered[activeFiltered.length - 1];
                last_activity_title_bar = lastFilteredObject.titleBar || null;
                last_activity_str = toLocalString(getActivityEndTime(lastFilteredObject));
            }
        }
    }

    const baseActivityData = {
        name: sources.itemName,
        json_activity_count: sources.activityPart2.length,
        filter_range: filterRange,
        raw_first_activity_time: rawFirstTime,
        raw_last_activity_time: rawLastTime,
        first_filtered_activity: first_activity_str,
        last_filtered_activity: last_activity_str,
        last_filtered_activity_titleBar: last_activity_title_bar
    };

    if (!first_activity_str || !last_activity_str) {
        return {
            ...baseActivityData,
            isMatch: false,
            missingLog: "Both",
            closestMissedTimestamp: null,
            isLate: false,
            lateMinutes: 0,
            isUnderTime: false,
            underTimeMinutes: 0,
            matchedLogs: [],
            originalLogs: sources.standardLogs,
            matchedSource: "None",
            errorReason: "No Activity Data Available"
        };
    }

    const firstTime = new Date(first_activity_str).getTime();
    const lastTime = new Date(last_activity_str).getTime();

    // Core Matching Engine
    function evaluateData(testLogs, sourceName) {
        if (!testLogs || testLogs.length === 0) {
            return { isMatch: false, matchedSource: sourceName };
        }

        const expectedIn = testLogs.some(l => l.type === "In");
        const expectedOut = testLogs.some(l => l.type === "Out");

        let bestInLog = null;
        let bestOutLog = null;
        let minInDiff = Infinity;
        let minOutDiff = Infinity;

        for (const log of testLogs) {
            const logTime = getLogTime(log);
            if (Number.isNaN(logTime)) continue;

            if (log.type === "In") {
                if (logTime >= (firstTime - THIRTY_MINUTES) && logTime <= (firstTime + TWO_MINUTES)) {
                    const diff = Math.abs(firstTime - logTime);
                    if (diff < minInDiff) {
                        minInDiff = diff;
                        bestInLog = log;
                    }
                }
            }

            if (log.type === "Out") {
                if (logTime >= (lastTime - FIFTEEN_MINUTES) && logTime <= (lastTime + ONE_HOUR)) {
                    const diff = Math.abs(lastTime - logTime);
                    if (diff < minOutDiff) {
                        minOutDiff = diff;
                        bestOutLog = log;
                    }
                }
            }
        }

        const matchedLogs = [];
        if (bestInLog) matchedLogs.push(bestInLog);
        if (bestOutLog) matchedLogs.push(bestOutLog);

        const hasIn = !!bestInLog;
        const hasOut = !!bestOutLog;

        let matchType = "None";
        let isMatchStatus = false;

        if (hasIn && hasOut) matchType = "Both";
        else if (hasIn) matchType = "In";
        else if (hasOut) matchType = "Out";

        if (expectedIn && expectedOut) {
            if (hasIn && hasOut) isMatchStatus = true;
            else if (hasIn || hasOut) isMatchStatus = "Partial";
        } else if (expectedIn) {
            if (hasIn) isMatchStatus = true;
        } else if (expectedOut) {
            if (hasOut) isMatchStatus = true;
        }

        let missingLog = "None";
        let expectedTimestamp = null;

        if (expectedIn && expectedOut) {
            if (matchType === "In") missingLog = "Out";
            else if (matchType === "Out") missingLog = "In";
            else if (matchType === "None") missingLog = "Both";
        } else if (expectedIn && !hasIn) {
            missingLog = "In";
        } else if (expectedOut && !hasOut) {
            missingLog = "Out";
        }

        if (missingLog === "In") expectedTimestamp = first_activity_str;
        else if (missingLog === "Out") expectedTimestamp = last_activity_str;

        let lateMinutes = 0;
        let underTimeMinutes = 0;

        if (hasIn && expectedIn) {
            const inLogTime = getLogTime(bestInLog);
            if (!Number.isNaN(inLogTime) && firstTime > inLogTime) {
                lateMinutes = Math.floor((firstTime - inLogTime) / (60 * 1000));
            }
        }

        if (hasOut && expectedOut) {
            const outLogTime = getLogTime(bestOutLog);
            if (!Number.isNaN(outLogTime) && lastTime < outLogTime) {
                underTimeMinutes = Math.floor((outLogTime - lastTime) / (60 * 1000));
            }
        }

        const outputData = {
            isMatch: isMatchStatus,
            missingLog: missingLog,
            closestMissedTimestamp: expectedTimestamp,
            isLate: lateMinutes > 0,
            lateMinutes: lateMinutes,
            isUnderTime: underTimeMinutes > 0,
            underTimeMinutes: underTimeMinutes,
            matchedLogs: matchedLogs,
            originalLogs: testLogs,
            matchedSource: sourceName
        };

        if (testLogs.length >= 2) outputData.matchType = matchType;
        if (outputData.isMatch === false && testLogs.length > 0) {
            if (testLogs[0].type === "In") outputData.originalLog = first_activity_str;
            else if (testLogs[0].type === "Out") outputData.originalLog = last_activity_str;
        }
        return outputData;
    }

    // 3. Build Schedule Logs
    let scheduleLogs = [];

    if (fallbackScheduleLogs) {
        scheduleLogs = fallbackScheduleLogs;
    } else {
        const rawScheduleText = sources.rawScheduleText;
        const rawSchedule2 = sources.rawSchedule2;

        if (rawScheduleText && typeof rawScheduleText === 'string' && rawScheduleText.includes(' - ')) {
            const parts = rawScheduleText.split(' - ');
            function parseTime(timeStr) {
                const [time, modifier] = timeStr.trim().split(' ');
                let [hours, minutes] = time.split(':');
                hours = parseInt(hours, 10);
                minutes = parseInt(minutes, 10);
                if (hours === 12 && modifier === 'AM') hours = 0;
                if (hours < 12 && modifier === 'PM') hours += 12;
                return { hours, minutes };
            }

            const baseDate = first_activity_str ? first_activity_str.split('T')[0] : toLocalString(windowStartMs).split('T')[0];
            let inParts = parseTime(parts[0]);
            let outParts = parseTime(parts[1]);

            let inTimeStr = `${baseDate}T${String(inParts.hours).padStart(2, '0')}:${String(inParts.minutes).padStart(2, '0')}:00+08:00`;
            let outTimeStr = `${baseDate}T${String(outParts.hours).padStart(2, '0')}:${String(outParts.minutes).padStart(2, '0')}:00+08:00`;

            let inMs = new Date(inTimeStr).getTime();
            let outMs = new Date(outTimeStr).getTime();

            if (outMs < inMs) {
                outMs += (24 * 60 * 60 * 1000);
                outTimeStr = new Date(outMs).toISOString();
            }

            scheduleLogs.push({ type: "In", dateTime: inTimeStr });
            scheduleLogs.push({ type: "Out", dateTime: outTimeStr });
        } else if (rawSchedule2 && rawSchedule2 !== false) {
            const schedArray = Array.isArray(rawSchedule2) ? rawSchedule2 : [rawSchedule2];
            for (const s of schedArray) {
                if (s.start) scheduleLogs.push({ type: "In", dateTime: s.start });
                if (s.strict_end) scheduleLogs.push({ type: "Out", dateTime: s.strict_end });
                else if (s.end) scheduleLogs.push({ type: "Out", dateTime: s.end });
            }
        }
    }

    const standardLogs = sources.standardLogs;
    let filteredScheduleLogs = [...scheduleLogs];
    if (standardLogs.length > 0) {
        const requestedIn = standardLogs.some(l => l.type === "In");
        const requestedOut = standardLogs.some(l => l.type === "Out");
        if (!requestedIn) filteredScheduleLogs = filteredScheduleLogs.filter(l => l.type !== "In");
        if (!requestedOut) filteredScheduleLogs = filteredScheduleLogs.filter(l => l.type !== "Out");
    }

    const logResult = evaluateData(standardLogs, "Logs");
    const scheduleResult = evaluateData(filteredScheduleLogs, "Schedule");

    function getMatchScore(res) {
        if (res.isMatch === true) return 2;
        if (res.isMatch === "Partial") return 1;
        return 0;
    }

    const logScore = getMatchScore(logResult);
    const schedScore = getMatchScore(scheduleResult);
    const logPenalty = (logResult.lateMinutes || 0) + (logResult.underTimeMinutes || 0);
    const schedPenalty = (scheduleResult.lateMinutes || 0) + (scheduleResult.underTimeMinutes || 0);

    let finalResult = logResult;
    if (schedScore > logScore) {
        finalResult = scheduleResult;
    } else if (schedScore === logScore && schedScore > 0) {
        if (schedPenalty < logPenalty) {
            finalResult = scheduleResult;
        }
    }

    return { ...baseActivityData, ...finalResult, originalLogs: standardLogs };
}


// ==========================================
// PART 4: ACTIVTRAK EXECUTION & FALLBACK
// ==========================================
let bestActivtrakResult = runEvaluation("Original Input");

function getScore(res) {
    if (res.isMatch === true) return 2;
    if (res.isMatch === "Partial") return 1;
    return 0;
}

if (getScore(bestActivtrakResult) < 2 && sources.standardLogs.length > 0) {

    let baseTimeMs = sources.inString ? new Date(sources.inString).getTime() : 0;
    const firstLog = sources.standardLogs[0];
    if (firstLog && typeof firstLog.dateTime === 'string') {
        baseTimeMs = getLogTime(firstLog);
    }
    if (!baseTimeMs || Number.isNaN(baseTimeMs)) baseTimeMs = Date.now();

    const currentDayStr = toLocalString(baseTimeMs).split('T')[0];
    const prevDayStr = toLocalString(baseTimeMs - 24 * 60 * 60 * 1000).split('T')[0];

    const daysToTest = [prevDayStr, currentDayStr];
    let fallbacks = [];

    for (const d of daysToTest) {
        const currentD = new Date(`${d}T00:00:00+08:00`);
        const nextD = new Date(currentD.getTime() + 24 * 60 * 60 * 1000);
        const nextDayStr = nextD.toISOString().split('T')[0];

        fallbacks.push({
            name: `Fallback (11:00 PM - 07:00 AM)`,
            logs: [{ type: "In", dateTime: `${d}T23:00:00+08:00` }, { type: "Out", dateTime: `${nextDayStr}T07:00:00+08:00` }]
        });
        fallbacks.push({
            name: `Fallback (07:00 AM - 04:00 PM)`,
            logs: [{ type: "In", dateTime: `${d}T07:00:00+08:00` }, { type: "Out", dateTime: `${d}T16:00:00+08:00` }]
        });
        fallbacks.push({
            name: `Fallback (08:00 AM - 04:00 PM)`,
            logs: [{ type: "In", dateTime: `${d}T08:00:00+08:00` }, { type: "Out", dateTime: `${d}T16:00:00+08:00` }]
        });
        fallbacks.push({
            name: `Fallback (08:00 AM - 05:00 PM)`,
            logs: [{ type: "In", dateTime: `${d}T08:00:00+08:00` }, { type: "Out", dateTime: `${d}T17:00:00+08:00` }]
        });
    }

    for (const fb of fallbacks) {
        const fbResult = runEvaluation(fb.name, fb.logs);

        const currentBestScore = getScore(bestActivtrakResult);
        const fbScore = getScore(fbResult);

        const bestHasActivities = bestActivtrakResult.errorReason !== "No Activity Data Available";
        const fbHasActivities = fbResult.errorReason !== "No Activity Data Available";

        if (fbScore > currentBestScore) {
            bestActivtrakResult = fbResult;
            if (fbScore === 2) break;
        } else if (fbScore === currentBestScore && fbScore === 0) {
            if (!bestHasActivities && fbHasActivities) {
                bestActivtrakResult = fbResult;
            }
        }
    }
}


// ==========================================
// PART 5: STANDALONE ACTIVITY FILTER FOR SUGGESTIONS
// ==========================================
// The filtering inside runEvaluation uses the employee's filed
// request times to override the window — but those filed times
// may be WRONG (that's the whole point of the anomaly scanner).
//
// This standalone filter uses the SCHEDULE window directly to
// find the true first/last activity for suggestion times.
//
// Sources needed:
//   - Activity data: $('HTTP Request16').item.json.activity  (activityPart1)
//                    $json.activity                          (activityPart2)
//   - Each activity object must have:
//       .time     → start time string (e.g. "2026-07-01T08:05:23" or with +08:00)
//       .duration → seconds (string or number, e.g. "3600" or 3600)
//       .titleBar → optional description string
//
// Filter window: schedule IN → schedule OUT + 5 min buffer
//   Falls back to broadest raw activity range if no schedule.
// ==========================================
const allActivities = [...(sources.activityPart1), ...(sources.activityPart2)];
let firstFilteredActivity = null;
let lastFilteredActivity = null;

if (allActivities.length > 0) {
    // Sort all activities chronologically
    const sortedAll = [...allActivities].sort((a, b) => getSafeTimeMs(a.time) - getSafeTimeMs(b.time));

    // Define the filter window from the SCHEDULE (not the filed request)
    // Fix: Force parsing using the timezone-safe string to prevent epoch shift on UTC servers
    let filterStart = null;
    let filterEnd = null;

    if (sources.inString) {
        filterStart = new Date(sources.inString).getTime();
    }
    if (sources.outString) {
        filterEnd = new Date(sources.outString).getTime() + (5 * 60 * 1000); // +5 min buffer
    }

    // If schedule is missing, try using the requestedLogs dates as a day reference
    // and use a broad window (midnight to midnight+24h) so we still capture activity
    if (filterStart === null || filterEnd === null) {
        let refDateMs = null;

        // Try to get a reference date from the requested logs
        if (requestedLogs.length > 0 && requestedLogs[0].dateTime) {
            refDateMs = getSafeTimeMs(requestedLogs[0].dateTime);
        }

        // If still no reference, use the earliest raw activity's date
        if (!refDateMs || refDateMs === 0) {
            refDateMs = getSafeTimeMs(sortedAll[0].time);
        }

        if (refDateMs && refDateMs > 0) {
            // Build a full-day window: midnight to midnight of the reference date
            const refDateStr = toLocalString(refDateMs).split('T')[0];
            filterStart = filterStart || new Date(`${refDateStr}T00:00:00+08:00`).getTime();
            filterEnd = filterEnd || new Date(`${refDateStr}T23:59:59+08:00`).getTime();
        }
    }

    // Handle night shift: if end < start, add 24 hours
    if (filterStart !== null && filterEnd !== null && filterEnd < filterStart) {
        filterEnd += (24 * 60 * 60 * 1000);
    }

    // Apply the filter
    let filtered;
    if (filterStart !== null && filterEnd !== null) {
        filtered = sortedAll.filter(a => {
            const t = getSafeTimeMs(a.time);
            return t >= filterStart && t <= filterEnd;
        });
    } else {
        // No window at all — use all activities as-is
        filtered = sortedAll;
    }

    if (filtered.length > 0) {
        filtered.sort((a, b) => getSafeTimeMs(a.time) - getSafeTimeMs(b.time));

        // Exclude "Passive" activities and offline IPs — they don't represent real work
        const activeFiltered = filtered.filter(a => a.titleBar !== "Passive" && a.publicIp !== "offline");

        if (activeFiltered.length > 0) {
            // first_filtered_activity = start time of the earliest non-passive activity
            firstFilteredActivity = activeFiltered[0].time;

            // last_filtered_activity = END time of the latest non-passive activity (start + duration)
            const lastObj = activeFiltered[activeFiltered.length - 1];
            lastFilteredActivity = toLocalString(getActivityEndTime(lastObj));
        }
    }
}


// ==========================================
// PART 6: REQUEST MATCHING ENGINE
// ==========================================
const validRequests = [];
const alreadyExistsRequests = [];
const conflictingRequests = [];

for (const reqLog of requestedLogs) {
    const reqTime = new Date(reqLog.dateTime);
    const reqTypeMode = reqLog.type?.toLowerCase() === 'in' ? 0 : 1;

    let relatedLogs = actualAttendanceLogsRaw.filter(actual => {
        const isEmpMatch = (requestData.employeeId == actual.id || requestData.employeeId == actual.bioEmpID);
        if (!isEmpMatch || actual.inOutMode !== reqTypeMode) return false;

        const diffHours = Math.abs(new Date(actual.logTime).getTime() - reqTime.getTime()) / (1000 * 60 * 60);
        return diffHours <= 4;
    });

    relatedLogs.sort((a, b) => {
        const diffA = Math.abs(new Date(a.logTime).getTime() - reqTime.getTime());
        const diffB = Math.abs(new Date(b.logTime).getTime() - reqTime.getTime());
        return diffA - diffB;
    });

    const relatedActualLog = relatedLogs.length > 0 ? relatedLogs[0] : null;

    if (relatedActualLog) {
        const actualTime = new Date(relatedActualLog.logTime);
        const diffMins = Math.abs(actualTime.getTime() - reqTime.getTime()) / (1000 * 60);

        // Determine correction direction:
        //   In punch: employee filed EARLIER than actual (correcting a late clock-in)
        //   Out punch: employee filed LATER than actual (correcting an early clock-out)
        const isCorrectionDirection = (
            (reqTypeMode === 0 && actualTime.getTime() > reqTime.getTime()) ||
            (reqTypeMode === 1 && actualTime.getTime() < reqTime.getTime())
        );

        if (diffMins <= 2) {
            // TIER 1: Under 2 minutes = essentially identical, always "already exists"
            // e.g. filed 23:15:00 vs actual 23:15:31 (31 sec diff)
            alreadyExistsRequests.push({
                ...reqLog,
                matchedActualTime: formatDateTimeMsg(actualTime)
            });
        } else if (isCorrectionDirection && diffMins <= 60) {
            // TIER 2: 2-60 min in correction direction = valid correction
            // e.g. filed In at 23:59 but actual In at 00:09 (10 min late, fixing delay)
            validRequests.push({
                ...reqLog,
                matchedActualTime: formatDateTimeMsg(actualTime),
                correctionNote: "Valid correction of a delayed or premature punch."
            });
        } else if (diffMins <= 15) {
            // TIER 3: 2-15 min but NOT correction direction = already exists
            // e.g. filed In at 08:10 but actual In at 08:05 (actual is earlier, no correction needed)
            alreadyExistsRequests.push({
                ...reqLog,
                matchedActualTime: formatDateTimeMsg(actualTime)
            });
        } else if (diffMins <= 120) {
            // TIER 4: 15-120 min and not a valid correction = conflict
            const exactHoursDiff = (Math.abs(actualTime.getTime() - reqTime.getTime()) / (1000 * 60 * 60)).toFixed(1);
            conflictingRequests.push({
                ...reqLog,
                conflictReason: `an actual '${reqLog.type}' punch is already recorded at ${formatDateTimeMsg(actualTime)} (${exactHoursDiff} hours away).`
            });
        } else {
            // TIER 5: > 2 hours away = unrelated punch from a different shift, disregard
            validRequests.push(reqLog);
        }
    } else {
        validRequests.push(reqLog);
    }
}


// ==========================================
// PART 6.5: SPROUT-BASED FILING TYPE DETECTION
// ==========================================
// Check Sprout actual attendance logs FIRST to determine what
// filing type is ACTUALLY needed (IN, OUT, or both).
// Then compare against what the doer filed to detect mismatches.
// ==========================================
let neededFilingTypes = [];
let wrongFilingType = false;
let wrongFilingDetails = null;

const filedDate = requestedLogs.length > 0 ? new Date(requestedLogs[0].dateTime) : null;
const filedTypes = [...new Set(requestedLogs.map(l => (l.type || '').toUpperCase()))].filter(Boolean);

if (filedDate && actualAttendanceLogsRaw.length > 0) {
    const isSameDayCheck = (d1, d2) => d1.getFullYear() === d2.getFullYear() && d1.getMonth() === d2.getMonth() && d1.getDate() === d2.getDate();

    // Get employee's existing Sprout punches near the filed date (±24h for night shifts)
    const employeeSproutLogs = actualAttendanceLogsRaw.filter(log => {
        const isEmpMatch = (requestData.employeeId == log.id || requestData.employeeId == log.bioEmpID);
        if (!isEmpMatch) return false;
        const logDate = new Date(log.logTime);
        const hoursDiff = Math.abs(logDate.getTime() - filedDate.getTime()) / (1000 * 60 * 60);
        return hoursDiff <= 24;
    });

    const hasExistingIn = employeeSproutLogs.some(l => l.inOutMode === 0);
    const hasExistingOut = employeeSproutLogs.some(l => l.inOutMode === 1);

    // Determine what's actually needed based on Sprout records
    if (hasExistingIn && !hasExistingOut) {
        neededFilingTypes = ['OUT'];
    } else if (!hasExistingIn && hasExistingOut) {
        neededFilingTypes = ['IN'];
    } else if (!hasExistingIn && !hasExistingOut) {
        neededFilingTypes = ['IN', 'OUT'];
    } else {
        neededFilingTypes = []; // Both already exist in Sprout
    }

    // Detect mismatch between what was filed vs what's needed
    if (neededFilingTypes.length > 0 && filedTypes.length > 0) {
        const filedUnnecessary = filedTypes.filter(t => !neededFilingTypes.includes(t));

        if (filedUnnecessary.length > 0) {
            wrongFilingType = true;

            const existingPunchDetails = [];
            if (hasExistingIn) {
                const inLog = employeeSproutLogs.find(l => l.inOutMode === 0);
                if (inLog) existingPunchDetails.push(`IN is already recorded at ${formatDateTimeMsg(new Date(inLog.logTime))}`);
            }
            if (hasExistingOut) {
                const outLog = employeeSproutLogs.find(l => l.inOutMode === 1);
                if (outLog) existingPunchDetails.push(`OUT is already recorded at ${formatDateTimeMsg(new Date(outLog.logTime))}`);
            }

            wrongFilingDetails = {
                filedTypes: filedTypes,
                neededTypes: neededFilingTypes,
                unnecessaryTypes: filedUnnecessary,
                existingPunchInfo: existingPunchDetails
            };
        }
    }
}


// ==========================================
// PART 7: EVALUATE REQUEST STATUS & SUGGESTIONS
// ==========================================
let finalStatus = "NO_ACTION_NEEDED";
let finalMessage = "No valid requested logs found to process.";
const suggestions = [];

const validCount = validRequests.length;
const conflictCount = conflictingRequests.length;
const dupCount = alreadyExistsRequests.length;

if (conflictCount > 0 && validCount === 0 && dupCount === 0) {
    finalStatus = "NOT_SATISFIED";
    finalMessage = "The request conflicts with existing attendance records.";
    const conflict = conflictingRequests[0];
    suggestions.push(`Conflict: ${conflict.conflictReason}`);
} else if (validCount > 0 && conflictCount === 0 && dupCount === 0) {
    finalStatus = "SATISFIED";
    finalMessage = "The filed request provides valid logs or permissible corrections.";
    suggestions.push("Great news! Your request is valid and fixes your missing or delayed time logs.");
} else if (validCount === 0 && dupCount > 0 && conflictCount === 0) {
    finalStatus = "UNNECESSARY_REQUEST";
    finalMessage = "All requested logs already exist perfectly in the actual attendance data.";
    suggestions.push("You can safely cancel this request! The exact times you submitted are actually already recorded.");
} else if (conflictCount > 0 || dupCount > 0) {
    finalStatus = "PARTIALLY_SATISFIED";
    finalMessage = "Some logs are valid, but others conflict with actual attendance records or already exist.";

    let logsToRefile = [...validRequests, ...conflictingRequests];

    if (logsToRefile.length > 0) {
        const refileStrings = logsToRefile.map(req => {
            const reqDate = new Date(req.dateTime);
            const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
            const monthStr = months[reqDate.getMonth()];
            const dayStr = reqDate.getDate();
            let hrs = reqDate.getHours();
            const ampm = hrs >= 12 ? 'pm' : 'am';
            hrs = hrs % 12;
            hrs = hrs ? hrs : 12;
            return `${monthStr} ${dayStr} clock ${req.type?.toLowerCase()} time at ${hrs}${ampm}`;
        }).join(" and ");

        suggestions.push(`Kindly refile for ${refileStrings} only.`);
    } else {
        suggestions.push("Please review your records. Part of your request is a duplicate.");
    }
}


// ==========================================
// PART 8: ANOMALY SCANNER (ACTIVITY-FIRST)
// ==========================================
// Suggestion time priority:
//   1. Filtered first/last ActivTrak activity (most accurate)
//   2. Schedule times (fallback)
//   3. +/-9 hours from the orphan punch (ultimate fallback)
// ==========================================
if ((finalStatus === "NOT_SATISFIED" || finalStatus === "NO_ACTION_NEEDED" || finalStatus === "UNNECESSARY_REQUEST") && validRequests.length === 0 && actualAttendanceLogsRaw.length > 0) {
    const isSameDay = (d1, d2) => d1.getFullYear() === d2.getFullYear() && d1.getMonth() === d2.getMonth() && d1.getDate() === d2.getDate();

    let targetRequestDate = null;
    let reqType = null;
    if (requestedLogs.length > 0) {
        targetRequestDate = new Date(requestedLogs[0].dateTime);
        reqType = requestedLogs[0].type?.toLowerCase();
    }

    const sortedLogs = [...actualAttendanceLogsRaw].sort((a, b) => new Date(a.logTime).getTime() - new Date(b.logTime).getTime());
    const employeeLogs = sortedLogs.filter(log => requestData.employeeId == log.id || requestData.employeeId == log.bioEmpID);
    const lastEmployeeLog = employeeLogs.length > 0 ? employeeLogs[employeeLogs.length - 1] : null;

    let anomalies = [];

    for (let i = 0; i < sortedLogs.length; i++) {
        const currentLog = sortedLogs[i];

        if (requestData.employeeId != currentLog.id && requestData.employeeId != currentLog.bioEmpID) continue;

        if (currentLog.inOutMode === 0) { // Found an IN punch
            let hasValidOut = false;
            let pairEndIndex = i;

            for (let j = i + 1; j < Math.min(i + 4, sortedLogs.length); j++) {
                const lookAheadLog = sortedLogs[j];
                if (requestData.employeeId != lookAheadLog.id && requestData.employeeId != lookAheadLog.bioEmpID) continue;

                if (lookAheadLog.inOutMode === 1) {
                    const diffHours = (new Date(lookAheadLog.logTime).getTime() - new Date(currentLog.logTime).getTime()) / (1000 * 60 * 60);
                    if (diffHours > 0 && diffHours <= 14) {
                        hasValidOut = true;
                        pairEndIndex = j;
                        break;
                    }
                }
            }

            if (hasValidOut) {
                i = pairEndIndex;
                continue;
            }

            // -------------------------------------------------------
            // MISSING OUT DETECTED — Determine suggestion time
            // Priority: 1) Last filtered activity  2) Schedule  3) +9hrs
            // -------------------------------------------------------
            let anomalyOut;
            let suggestionSource;

            if (lastFilteredActivity) {
                // PRIMARY: Use the last filtered ActivTrak activity end time
                anomalyOut = getLocalMasqueradeDate(lastFilteredActivity);
                suggestionSource = "Activity";
            } else if (scheduleTimeOut) {
                // FALLBACK: Use the schedule's OUT time
                const anomalyIn = new Date(currentLog.logTime);
                anomalyOut = new Date(anomalyIn.getTime());
                anomalyOut.setHours(scheduleTimeOut.getHours(), scheduleTimeOut.getMinutes(), 0, 0);
                if (anomalyOut <= anomalyIn) {
                    anomalyOut.setDate(anomalyOut.getDate() + 1);
                }
                suggestionSource = "Schedule";
            } else {
                // ULTIMATE FALLBACK: IN + 9 hours
                anomalyOut = new Date(new Date(currentLog.logTime).getTime() + NINE_HOURS_MS);
                suggestionSource = "Default (+9hrs)";
            }

            // Prevent suggesting an OUT punch if they already have one recorded for this date
            const hasExistingOut = sortedLogs.some(l =>
                l.inOutMode === 1 &&
                (requestData.employeeId == l.id || requestData.employeeId == l.bioEmpID) &&
                isSameDay(new Date(l.logTime), anomalyOut)
            );
            if (hasExistingOut) continue;

            if (lastEmployeeLog) {
                const lastLogDate = new Date(lastEmployeeLog.logTime);
                const anomalyInDate = new Date(currentLog.logTime);
                if (!isSameDay(anomalyInDate, lastLogDate) && !isSameDay(anomalyOut, lastLogDate)) continue;
            }

            if (targetRequestDate && !isSameDay(new Date(currentLog.logTime), targetRequestDate) && !isSameDay(anomalyOut, targetRequestDate)) continue;

            anomalies.push({ type: 'OUT', time: anomalyOut, source: suggestionSource });

        } else if (currentLog.inOutMode === 1) {
            // -------------------------------------------------------
            // MISSING IN DETECTED — Determine suggestion time
            // Priority: 1) First filtered activity  2) Schedule  3) -9hrs
            // -------------------------------------------------------
            let anomalyOut = new Date(currentLog.logTime);
            let anomalyIn;
            let suggestionSource;

            if (firstFilteredActivity) {
                // PRIMARY: Use the first filtered ActivTrak activity start time
                anomalyIn = getLocalMasqueradeDate(firstFilteredActivity);
                suggestionSource = "Activity";
            } else if (scheduleTimeIn) {
                // FALLBACK: Use the schedule's IN time
                anomalyIn = new Date(anomalyOut.getTime());
                anomalyIn.setHours(scheduleTimeIn.getHours(), scheduleTimeIn.getMinutes(), 0, 0);
                if (anomalyIn >= anomalyOut) {
                    anomalyIn.setDate(anomalyIn.getDate() - 1);
                }
                suggestionSource = "Schedule";
            } else {
                // ULTIMATE FALLBACK: OUT - 9 hours
                anomalyIn = new Date(anomalyOut.getTime() - NINE_HOURS_MS);
                suggestionSource = "Default (-9hrs)";
            }

            // Prevent suggesting an IN punch if they already have one recorded for this date
            const hasExistingIn = sortedLogs.some(l =>
                l.inOutMode === 0 &&
                (requestData.employeeId == l.id || requestData.employeeId == l.bioEmpID) &&
                isSameDay(new Date(l.logTime), anomalyIn)
            );
            if (hasExistingIn) continue;

            if (lastEmployeeLog) {
                const lastLogDate = new Date(lastEmployeeLog.logTime);
                if (!isSameDay(anomalyIn, lastLogDate) && !isSameDay(anomalyOut, lastLogDate)) continue;
            }

            if (targetRequestDate && !isSameDay(anomalyIn, targetRequestDate) && !isSameDay(anomalyOut, targetRequestDate)) continue;

            anomalies.push({ type: 'IN', time: anomalyIn, source: suggestionSource });
        }
    }

    // --- EVALUATE: Pick the best anomaly based on what the employee actually filed ---
    if (anomalies.length > 0) {
        let bestAnomaly = null;

        if (targetRequestDate && reqType) {
            const matchedTypeAnomalies = anomalies.filter(a => a.type.toLowerCase() === reqType);
            const candidates = matchedTypeAnomalies.length > 0 ? matchedTypeAnomalies : anomalies;

            candidates.sort((a, b) => Math.abs(a.time.getTime() - targetRequestDate.getTime()) - Math.abs(b.time.getTime() - targetRequestDate.getTime()));

            bestAnomaly = candidates[0];
        } else {
            bestAnomaly = anomalies[0];
        }

        if (bestAnomaly) {
            suggestions.length = 0;
            suggestions.push(`Refile and submit a new request for only ${bestAnomaly.type} punch on ${formatSuggestionDate(bestAnomaly.time)}.`);
            finalStatus = "WRONG_FILED_DATES";
            finalMessage = `The filed dates are invalid, but the system discovered a genuine missing punch anomaly. (Suggestion based on: ${bestAnomaly.source})`;
        }
    }
}


// ==========================================
// PART 8.5: AT UNDERTIME DETECTION + COMBINED ERROR TEMPLATE
// ==========================================
// 1. Check ActivTrack filtered first/last activity against schedule.
//    If undertime is detected, use AT times for the suggestion.
// 2. Detect wrong PST shift dates.
// 3. Build a combined template if multiple errors exist.
// ==========================================

// --- AT Undertime Detection ---
let undertimeDetected = false;
let lateStartDetected = false;
let atUndertimeMinutes = 0;
let atLateMinutes = 0;
let atSuggestedInTime = null;
let atSuggestedOutTime = null;

if (firstFilteredActivity && scheduleTimeIn) {
    const atFirstMs = getSafeTimeMs(firstFilteredActivity);
    const schedInMs = scheduleTimeIn.getTime();
    if (atFirstMs > schedInMs + TWO_MINUTES) {
        lateStartDetected = true;
        atLateMinutes = Math.floor((atFirstMs - schedInMs) / (60 * 1000));
        atSuggestedInTime = getLocalMasqueradeDate(firstFilteredActivity);
    }
}

if (lastFilteredActivity && scheduleTimeOut) {
    const atLastMs = getSafeTimeMs(lastFilteredActivity);
    const schedOutMs = scheduleTimeOut.getTime();
    if (atLastMs < schedOutMs - TWO_MINUTES) {
        undertimeDetected = true;
        atUndertimeMinutes = Math.floor((schedOutMs - atLastMs) / (60 * 1000));
        atSuggestedOutTime = getLocalMasqueradeDate(lastFilteredActivity);
    }
}

// Use AT activity times for filing suggestions when available
if (neededFilingTypes.length > 0) {
    if (neededFilingTypes.includes('IN') && firstFilteredActivity && !atSuggestedInTime) {
        atSuggestedInTime = getLocalMasqueradeDate(firstFilteredActivity);
    }
    if (neededFilingTypes.includes('OUT') && lastFilteredActivity && !atSuggestedOutTime) {
        atSuggestedOutTime = getLocalMasqueradeDate(lastFilteredActivity);
    }
}

// --- Detect Wrong PST Shift Dates ---
let wrongPstDates = false;
let wrongPstDetails = null;

if (filedDate && scheduleTimeIn && scheduleTimeOut) {
    const schedInDateStr = formatDateTimeT(scheduleTimeIn).split('T')[0];
    const schedOutDateStr = formatDateTimeT(scheduleTimeOut).split('T')[0];

    const hasDateMismatch = requestedLogs.some(log => {
        const logDate = new Date(log.dateTime);
        const logDateStr = formatDateTimeT(logDate)?.split('T')[0];
        return logDateStr && logDateStr !== schedInDateStr && logDateStr !== schedOutDateStr;
    });

    if (hasDateMismatch) {
        wrongPstDates = true;
        wrongPstDetails = {
            filedDate: formatSuggestionDate(filedDate),
            scheduleIn: formatSuggestionDate(scheduleTimeIn),
            scheduleOut: formatSuggestionDate(scheduleTimeOut)
        };
    }
}

// --- Collect All Error Flags ---
const errorFlags = [];
if (wrongFilingType) errorFlags.push('WRONG_FILING_TYPE');
if (wrongPstDates) errorFlags.push('WRONG_PST_SHIFT_DATES');
if (undertimeDetected) errorFlags.push('UNDERTIME_DETECTED');
if (lateStartDetected) errorFlags.push('LATE_START_DETECTED');
if (finalStatus === 'WRONG_FILED_DATES') errorFlags.push('WRONG_FILED_DATES');

// --- Reusable: Build Correction Suggestion Parts ---
function buildCorrectionParts() {
    const parts = [];
    const typesToSuggest = neededFilingTypes.length > 0 ? neededFilingTypes : filedTypes;

    for (const type of typesToSuggest) {
        if (type === 'IN' && atSuggestedInTime) {
            parts.push(`IN punch on ${formatSuggestionDate(atSuggestedInTime)} (based on ActivTrack first activity)`);
        } else if (type === 'OUT' && atSuggestedOutTime) {
            parts.push(`OUT punch on ${formatSuggestionDate(atSuggestedOutTime)} (based on ActivTrack last activity)`);
        } else if (type === 'IN' && scheduleTimeIn) {
            parts.push(`IN punch on ${formatSuggestionDate(scheduleTimeIn)} (based on schedule)`);
        } else if (type === 'OUT' && scheduleTimeOut) {
            parts.push(`OUT punch on ${formatSuggestionDate(scheduleTimeOut)} (based on schedule)`);
        }
    }
    return parts;
}

// --- Combined Error Template (2+ errors) ---
if (errorFlags.length >= 2) {
    suggestions.length = 0;
    const issuesList = [];
    let issueNum = 1;

    if (wrongFilingType && wrongFilingDetails) {
        const neededStr = wrongFilingDetails.neededTypes.join(' and ');
        const existingInfo = wrongFilingDetails.existingPunchInfo.join('; ');
        issuesList.push(`${issueNum}. Wrong filing type: You filed for ${wrongFilingDetails.filedTypes.join(' and ')}, but only ${neededStr} punch is needed (${existingInfo}).`);
        issueNum++;
    }

    if (wrongPstDates && wrongPstDetails) {
        issuesList.push(`${issueNum}. Wrong shift dates: Your filed dates (${wrongPstDetails.filedDate}) don't match your PST shift schedule (${wrongPstDetails.scheduleIn} – ${wrongPstDetails.scheduleOut}).`);
        issueNum++;
    }

    if (undertimeDetected) {
        issuesList.push(`${issueNum}. Undertime detected: ActivTrack shows your last activity ended ${atUndertimeMinutes} minutes before your scheduled end time.`);
        issueNum++;
    }

    if (lateStartDetected) {
        issuesList.push(`${issueNum}. Late start detected: ActivTrack shows your first activity started ${atLateMinutes} minutes after your scheduled start time.`);
        issueNum++;
    }

    if (finalStatus === 'WRONG_FILED_DATES' && !wrongFilingType && !wrongPstDates) {
        issuesList.push(`${issueNum}. Wrong filed dates: The dates in your request don't match any detected attendance anomaly.`);
        issueNum++;
    }

    const correctionParts = buildCorrectionParts();
    const correctionStr = correctionParts.length > 0
        ? `\n\nSuggested correction: Refile for ${correctionParts.join(' and ')}.`
        : '';

    suggestions.push(issuesList.join('\n') + correctionStr);
    finalStatus = "MULTIPLE_ERRORS";
    finalMessage = `Multiple issues detected with this request: ${errorFlags.join(', ')}.`;

} else if (errorFlags.length === 1) {
    // --- Single Error Enhancement ---

    // Wrong filing type only
    if (wrongFilingType && wrongFilingDetails) {
        suggestions.length = 0;
        const neededStr = wrongFilingDetails.neededTypes.join(' and ');
        const existingInfo = wrongFilingDetails.existingPunchInfo.join('; ');
        const correctionParts = buildCorrectionParts();
        const correctionStr = correctionParts.length > 0
            ? ` Suggested correction: Refile for ${correctionParts.join(' and ')}.`
            : '';

        suggestions.push(`Wrong filing type: You filed for ${wrongFilingDetails.filedTypes.join(' and ')}, but only ${neededStr} punch is needed (${existingInfo}).${correctionStr}`);
        finalStatus = "WRONG_FILING_TYPE";
        finalMessage = `The doer filed for the wrong punch type. ${existingInfo}.`;
    } else if (wrongPstDates && wrongPstDetails) {
        suggestions.length = 0;
        suggestions.push(`Wrong shift dates: Your filed dates (${wrongPstDetails.filedDate}) don't match your PST shift schedule (${wrongPstDetails.scheduleIn} – ${wrongPstDetails.scheduleOut}).`);
        finalStatus = "WRONG_PST_SHIFT_DATES";
        finalMessage = "The filed request dates do not match the PST schedule.";
    } else if (undertimeDetected && atSuggestedOutTime) {
        // Force overwrite SATISFIED if undertime is detected!
        suggestions.length = 0;
        suggestions.push(`Refile and submit a new request for only OUT punch on ${formatSuggestionDate(atSuggestedOutTime)} (based on ActivTrack last activity — undertime of ${atUndertimeMinutes} minutes detected).`);
        finalStatus = "UNDERTIME_DETECTED";
        finalMessage = `ActivTrack shows undertime. Last activity ended ${atUndertimeMinutes} minutes early.`;
    } else if (lateStartDetected && atSuggestedInTime) {
        // Force overwrite SATISFIED if late start is detected!
        suggestions.length = 0;
        suggestions.push(`Refile and submit a new request for only IN punch on ${formatSuggestionDate(atSuggestedInTime)} (based on ActivTrack first activity — late start of ${atLateMinutes} minutes detected).`);
        finalStatus = "LATE_START_DETECTED";
        finalMessage = `ActivTrack shows a late start. First activity started ${atLateMinutes} minutes late.`;
    }
}


// ==========================================
// PART 9: BUILD COMBINED OUTPUT
// ==========================================
const inoutCalculation = {
    name: doerName,
    rawSchedule: scheduleStr || "Not Provided",
    in: scheduleTimeIn ? formatDateTimeT(scheduleTimeIn) : null,
    out: scheduleTimeOut ? formatDateTimeT(scheduleTimeOut) : null,
    logs: requestedLogs
};

const simplifiedActualLogs = actualAttendanceLogsRaw.map(log => ({
    employeeId: log.bioEmpID || log.id,
    type: log.inOutMode === 0 ? "In" : "Out",
    time: formatDateTimeMsg(new Date(log.logTime))
}));

return {
    json: {
        // --- Request Analysis Results ---
        status: finalStatus,
        message: finalMessage,
        suggestions: suggestions,
        metrics: {
            totalCorrectionsFiled: requestedLogs.length,
            validNewPunches: validRequests.length,
            alreadyExistingPunches: alreadyExistsRequests.length,
            conflictingOverrides: conflictingRequests.length,
            removedNonBiometricCount: removedNonBiometricLogs.length
        },
        inout: inoutCalculation,
        validRequestedLogs: validRequests,
        alreadyExistsLogs: alreadyExistsRequests,
        conflictingLogs: conflictingRequests,
        removedNonBiometricLogs: removedNonBiometricLogs,
        submittedRequestDetails: requestData,
        actualAttendanceLogs: simplifiedActualLogs,
        // --- Sprout Filing Type Analysis ---
        sproutFilingAnalysis: {
            neededFilingTypes: neededFilingTypes,
            wrongFilingType: wrongFilingType,
            wrongFilingDetails: wrongFilingDetails
        },
        // --- AT Undertime Analysis ---
        atUndertimeAnalysis: {
            undertimeDetected: undertimeDetected,
            lateStartDetected: lateStartDetected,
            atUndertimeMinutes: atUndertimeMinutes,
            atLateMinutes: atLateMinutes,
            atSuggestedInTime: atSuggestedInTime ? formatDateTimeMsg(atSuggestedInTime) : null,
            atSuggestedOutTime: atSuggestedOutTime ? formatDateTimeMsg(atSuggestedOutTime) : null,
            firstFilteredActivity: firstFilteredActivity,
            lastFilteredActivity: lastFilteredActivity
        },
        // --- Error Flags ---
        errorFlags: errorFlags || [],
        // --- ActivTrak Evaluation Results (flat, sanitized) ---
        ...JSON.parse(JSON.stringify(bestActivtrakResult))
    }
};
